[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$ReceiptPath,[string]$EnvironmentLockPath='')
$ErrorActionPreference='Stop';$issues=[Collections.Generic.List[string]]::new();$r=Get-Content -Raw -Encoding UTF8 -LiteralPath $ReceiptPath|ConvertFrom-Json
if($r.schemaVersion -ne 1){$issues.Add('SCHEMA_VERSION')};if($r.recordType -ne 'WebPageStudioRuntimeReceipt'){$issues.Add('RECORD_TYPE')};foreach($n in 'receiptId','status','browser','environment','viewport','artifact','snapshot','visualChecks','runtimeStatus','nonClaims'){if($null -eq $r.PSObject.Properties[$n]){$issues.Add("MISSING_$n")}}
if($r.environment.network -ne 'disabled'){$issues.Add('NETWORK_MUST_BE_DISABLED')};if($r.viewport.width -lt 1 -or $r.viewport.height -lt 1){$issues.Add('VIEWPORT_INVALID')};foreach($h in @($r.environment.fontManifestHash,$r.artifact.htmlHash,$r.snapshot.screenshotHash,$r.snapshot.domHash,$r.snapshot.ariaHash)){if([string]$h -notmatch '^[a-f0-9]{64}$'){$issues.Add('HASH_INVALID')}};if($r.status -eq 'passed' -and $r.runtimeStatus -ne 'runtime-passed'){$issues.Add('PASSED_STATUS')};if($r.status -eq 'not-run' -and $r.runtimeStatus -ne 'runtime-not-run'){$issues.Add('NOT_RUN_STATUS')}
if($r.status -eq 'passed' -and [int]$r.snapshot.nodeCount -lt 1){$issues.Add('DOM_EMPTY')};if([int]$r.snapshot.interactiveCount -gt [int]$r.snapshot.nodeCount){$issues.Add('INTERACTIVE_COUNT_INVALID')};if($r.status -eq 'passed' -and @($r.visualChecks | Where-Object { $_.category -in @('geometry','token','pixel') -and $_.status -eq 'passed' }).Count -lt 1){$issues.Add('VISUAL_CHECK_MISSING')}
if($EnvironmentLockPath){$lock=Get-Content -Raw -Encoding UTF8 -LiteralPath $EnvironmentLockPath|ConvertFrom-Json;if([string]$lock.engine -ne [string]$r.browser.engine -or [string]$lock.locale -ne [string]$r.environment.locale -or [string]$lock.timezone -ne [string]$r.environment.timezone -or [string]$lock.network -ne [string]$r.environment.network -or [string]$lock.version -ne [string]$r.browser.version -or [string]$lock.fontManifestHash -ne [string]$r.environment.fontManifestHash){$issues.Add('ENVIRONMENT_LOCK_DRIFT')};if($r.environment.PSObject.Properties['environmentLockHash']){$lockHash=(Get-FileHash -LiteralPath $EnvironmentLockPath -Algorithm SHA256).Hash.ToLowerInvariant();if([string]$r.environment.environmentLockHash -cne $lockHash){$issues.Add('ENVIRONMENT_LOCK_HASH_DRIFT')}}}
$o=[ordered]@{validator='preview-runtime-receipt';status=if($issues.Count){'blocked'}else{'passed'};findingCount=$issues.Count;findings=@($issues);runtimeStatus=[string]$r.runtimeStatus;nonClaims=@('screenshot-does-not-prove-human-signoff','network-is-disabled')};$o|ConvertTo-Json -Depth 8;if($issues.Count){exit 1}
